using System;using UnityEngine;using Random = UnityEngine.Random;public class EnemyBehavior : MonoBehaviour{    public GameObject player;    private float badguyspeed;    private float stopdistance;    [SerializeField] private float _shottimer;    public GameObject enemybullet;    private bool _hasshot;    private Rigidbody _enemyrb;    [SerializeField] private bool _hit;    private float _koTimer;    [SerializeField]  private bool _rise;            // Start is called once before the first execution of Update after the MonoBehaviour is created    void Start()    {        badguyspeed = 1f;        stopdistance = 5f;        _shottimer = 0.5f;        _hasshot = false;        _enemyrb = GetComponent<Rigidbody>();        _hit= false;        _koTimer = 5f;       _rise = false;           }    // Update is called once per frame    void Update()    {        _shottimer -= 1 * Time.deltaTime;        if (_hit)        {            _koTimer -= 1 * Time.deltaTime;        }        if (_koTimer <= 0)        {            _rise = true;        }                if (_koTimer <= -1)        {            _rise = false;            _hit = false;        }        if (_rise)        {            transform.rotation = Quaternion.Lerp(transform.rotation, Quaternion.identity, 10f * Time.deltaTime);            transform.position += Vector3.up * 1 * Time.deltaTime;        }               if (_shottimer <= 0)        {            _shottimer = Random.Range(1f, 1.5f);            _hasshot = false;        }        if (_shottimer <= 0.1 && _hasshot == false && !_hit)        {            Instantiate(enemybullet, transform.position + transform.forward * 0.15f, transform.rotation);            _hasshot = true;        }    }    private void FixedUpdate()    {        float _distance = Vector3.Distance(player.transform.position, transform.position);                if (_distance < stopdistance)        {            badguyspeed = 0f;        }        if (!_hit && _distance >= stopdistance)        {            badguyspeed = 1f;            transform.position =                Vector3.MoveTowards(transform.position, player.transform.position - new Vector3(stopdistance,0,stopdistance), Time.fixedDeltaTime * badguyspeed);                     }                if (!_hit)        {            transform.LookAt(player.transform);        }    }    private void OnTriggerEnter(Collider other)    {        if (other.CompareTag("playerbullet"))        {            _enemyrb.constraints = RigidbodyConstraints.None;            _hit = true;            Debug.Log("hit");            _koTimer = 5f;                    }    }}